// Gridline — Q-13 interface icons: SVG sources rasterised into an alpha atlas.
//
// The icons are drawn as SVG on a 24-unit grid (assets/icons/ui/*.svg: Lucide
// and Tabler geometry, see NOTICE.md there). They are embedded at build time
// (IconData.cpp, generated by cmake/EmbedIcons.cmake) and rasterised here with
// nanosvg at the exact device-pixel size they are shown at: the UI scale times
// the display density. Each (icon, size) is rasterised once and packed into
// 512 x 512 alpha pages; a density change clears the atlas so every icon is
// rasterised again, crisp, at its new size. Nothing here touches ImGui or GL:
// IconTexture.cpp uploads the pages and draws tinted quads from them.
#pragma once
#include <cstdint>
#include <memory>
#include <string>
#include <unordered_map>
#include <vector>

namespace gl::icons {

// One embedded SVG: file stem (e.g. "pencil") and its text.
struct SvgSource {
  const char* name;
  const char* svg;
};
// Every embedded SVG (generated from assets/icons/ui/*.svg at build time).
const SvgSource* embeddedSvgs(int* count);
// SVG text of the named icon, or nullptr.
const char* findSvg(const std::string& name);

// Stroke width in device pixels for an icon box of `logicalPx` at `density`:
// the 24-unit grid's 2-unit stroke, never thinner than 1.5 logical pixels.
float strokePx(float logicalPx, float density);

// Rasterises SVG text into an alpha bitmap of px x px device pixels (the
// 24-unit viewBox fills the box). Strokes are drawn `strokeDevicePx` wide.
// The shape is supersampled (exact area coverage) and nudged by at most half a
// pixel so straight strokes land on whole pixels (crisp edges at 1x).
// Returns false when the SVG does not parse.
bool rasterize(const char* svgText, int px, float strokeDevicePx, std::vector<uint8_t>& alpha);

// Geometry bounds of the SVG's shapes in viewBox units (stroke not included):
// out = {minX, minY, maxX, maxY}; *stroked = any shape is stroked. False when
// the SVG does not parse or draws nothing.
bool geometryBounds(const char* svgText, float out[4], bool* stroked);

class Atlas {
 public:
  static constexpr int kPage = 512;  // page edge, texels
  static constexpr int kPad = 1;     // empty texels around each icon (bilinear safety)
  struct Rect {
    int page = -1, x = 0, y = 0, size = 0;  // texels; size = device px of the 24-unit box
    // Ink bounds inside the box (device px, exclusive end): texels with at least
    // kInkAlpha coverage. Used to fit an icon to the footprint of the glyph it
    // replaces (IconTexture.h drawFit). Empty (0,0,0,0) for a blank icon.
    int inkX0 = 0, inkY0 = 0, inkX1 = 0, inkY1 = 0;
  };
  static constexpr int kInkAlpha = 16;  // coverage counted as ink (any visible edge texel)
  struct Page {
    std::vector<uint8_t> alpha;              // kPage * kPage coverage
    int shelfY = 0, shelfH = 0, cursorX = 0;  // shelf packer
    int dirtyX0 = kPage, dirtyY0 = kPage, dirtyX1 = 0, dirtyY1 = 0;  // texels written since takeDirty
    bool cleared = false;                    // whole page changed (density reset)
  };

  Atlas();
  ~Atlas();
  Atlas(const Atlas&) = delete;
  Atlas& operator=(const Atlas&) = delete;

  // Display density (device px per logical px). A change clears every icon so
  // the next lookups rasterise again at the new size. Returns true if cleared.
  bool setDensity(float density);
  float density() const { return density_; }
  // Device-pixel box for an icon shown `logicalPx` wide at the current density.
  int devicePx(float logicalPx) const;
  // The icon's rect, rasterising it on first use at this size. nullptr when
  // the icon is unknown or does not fit.
  const Rect* get(const std::string& name, float logicalPx);
  // Same, by index into embeddedSvgs(). `strokeDevicePx` > 0 replaces the
  // stroke rule's width (device px): used to fit icons to glyphs drawn thinner.
  const Rect* get(int svgIndex, float logicalPx, float strokeDevicePx = 0);
  int indexOf(const std::string& name) const;

  const std::vector<Page>& pages() const { return pages_; }
  std::vector<Page>& pages() { return pages_; }
  // Counters for tests / diagnostics.
  int rasterCount() const { return rasterCount_; }  // rasterisations since construction
  int entryCount() const { return static_cast<int>(rects_.size()); }
  int resetCount() const { return resets_; }
  void clear();

 private:
  bool place(int w, int h, Rect& out);
  float density_ = 1.0f;
  std::vector<Page> pages_;
  std::unordered_map<uint64_t, Rect> rects_;
  std::unordered_map<std::string, int> index_;
  int rasterCount_ = 0, resets_ = 0;
};

}  // namespace gl::icons
